begin;
do $$
declare org uuid:=gen_random_uuid(); actor uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); c bigint; v bigint; p bigint; q bigint; w bigint; pur bigint; inv bigint; ret bigint; cp bigint; vp bigint; est bigint; result jsonb; preview jsonb; before_count bigint; snapshot jsonb;
begin
 insert into auth.users(id) values(actor);
 insert into public.organizations(id,name,slug) values(org,'Reversal regression',org::text);
 insert into public.organization_memberships(organization_id,user_id,role,status) values(org,actor,'owner','active');
 insert into public.branches(id,organization_id,code,name,status) values(b,org,'R','Reversal branch','active');
 insert into public.branch_access_grants(organization_id,branch_id,user_id,status) values(org,b,actor,'active');
 insert into public.customers(organization_id,name,phone,city) values(org,'Test customer','0','Test') returning id into c;
 insert into public.vendors(organization_id,name,phone,city) values(org,'Test vendor','0','Test') returning id into v;
 insert into public.products(organization_id,name,sku,category,unit,purchase_price,sale_price) values(org,'Pipe',org::text||'p','Test','piece',1200,1312) returning id into p;
 insert into public.products(organization_id,name,sku,category,unit,purchase_price,sale_price) values(org,'Elbow',org::text||'q','Test','piece',300,360) returning id into q;
 insert into public.warehouses(organization_id,name) values(org,'Test warehouse') returning id into w;
 result:=public.record_purchase(org,b,actor,'reversal-regression','purchase.create',v,w,jsonb_build_array(jsonb_build_object('product_id',p,'quantity',5,'unit_cost',1200),jsonb_build_object('product_id',q,'quantity',5,'unit_cost',300)),'purchase',repeat('1',64));
 pur:=(result->'response_body'->'data'->'purchase'->>'id')::bigint;
 result:=public.post_invoice_atomic(org,b,actor,'reversal-regression','sales.invoice.post','invoice',repeat('2',64),jsonb_build_object('invoice_number','REVERSAL-INV','customer_id',c,'issue_date',current_date,'currency_code','PKR','subtotal',1672,'discount_total',0,'grand_total',1672,'pass_through_rent',0),jsonb_build_array(jsonb_build_object('line_number',1,'product_id',p,'quantity',1,'unit','piece','unit_price',1312,'line_total',1312,'unit_cost',1200,'cogs_total',1200),jsonb_build_object('line_number',2,'product_id',q,'quantity',1,'unit','piece','unit_price',360,'line_total',360,'unit_cost',300,'cogs_total',300)),w);
 inv:=(result->>'invoice_id')::bigint;
 result:=public.record_customer_payment(org,b,actor,'reversal-regression','customer-payment.create',c,current_date,1672,'PKR','CASH',null,null,jsonb_build_array(jsonb_build_object('invoice_id',inv,'amount',1672)),'payment',repeat('3',64));
 cp:=(result->'payment'->>'id')::bigint;
 vp:=public.record_vendor_payment(org,b,actor,'reversal-regression','vendor-payment.create',v,1000,'CASH',jsonb_build_array(jsonb_build_object('purchase_id',pur,'amount',1000)),current_date,null,null,'vendor-payment',repeat('4',64));
 result:=public.record_sales_return(org,b,actor,'reversal-regression','sales-return.create','REVERSAL-RETURN',inv,c,current_date,'PKR','Return',null,jsonb_build_array(jsonb_build_object('invoice_item_id',(select id from public.invoice_items where invoice_id=inv and product_id=q),'warehouse_id',w,'quantity',1)),'return',repeat('5',64));
 ret:=(result->'credit_note'->>'id')::bigint;
 if ret is null or cp is null or pur is null then raise exception 'Fixture response identifiers missing: %, %, %',ret,cp,pur;end if;
 insert into public.estimates(organization_id,branch_id,customer_id,estimate_number,issue_date,currency_code,status) values(org,b,c,'TEST-EST',current_date,'PKR','DRAFT') returning id into est;
 -- Real-world cleanup history: return removal at zero stock must fail atomically.
 perform public.adjust_stock_atomic(org,b,actor,p,w,-4,'Test cleanup','Regression');
 perform public.adjust_stock_atomic(org,b,actor,q,w,-5,'Test cleanup','Regression');
 preview:=public.reverse_record_atomic('credit_notes',ret,org,b,actor,'DELETE',true);
 if (preview->>'allowed')::boolean or preview->'blockers'='[]' then raise exception 'Negative stock preview accepted';end if;
 select count(*) into before_count from public.audit_logs where organization_id=org;
 begin perform public.reverse_record_atomic('credit_notes',ret,org,b,actor);raise exception 'Negative stock delete accepted';exception when check_violation then null;end;
 if not exists(select 1 from public.credit_notes where id=ret) or (select quantity from public.inventory where product_id=q and warehouse_id=w)<>0 or (select count(*) from public.audit_logs where organization_id=org)<>before_count then raise exception 'Failed delete leaked effects';end if;
 begin perform public.reverse_record_atomic('invoices',inv,org,b,actor);raise exception 'Dependent invoice accepted';exception when check_violation then null;end;
 begin perform public.reverse_record_atomic('customers',c,org,b,actor);raise exception 'Dependent customer accepted';exception when check_violation then null;end;
 -- Authorized compensations restore the two cleanup adjustments first.
 perform public.adjust_stock_atomic(org,b,actor,p,w,4,'Reverse test cleanup','Regression');
 perform public.adjust_stock_atomic(org,b,actor,q,w,5,'Reverse test cleanup','Regression');
 preview:=public.reverse_record_atomic('credit_notes',ret,org,b,actor,'DELETE',true);
 if not (preview->>'allowed')::boolean or (select count(*) from public.audit_logs where organization_id=org)<>before_count then raise exception 'Preview changed data';end if;
 begin perform public.reverse_record_atomic('credit_notes',ret,org,b,actor,'DELETE',false,repeat('0',32));raise exception 'Stale confirmation accepted';exception when check_violation then null;end;
 perform public.reverse_record_atomic('credit_notes',ret,org,b,actor,'DELETE',false,preview->>'fingerprint');
 perform public.reverse_record_atomic('customer_payments',cp,org,b,actor);
 if (select status from public.invoices where id=inv)<>'POSTED' then raise exception 'Invoice payment status was not recomputed';end if;
 perform public.reverse_record_atomic('vendor_payments',vp,org,b,actor);
 perform public.reverse_record_atomic('invoices',inv,org,b,actor);
 perform public.reverse_record_atomic('purchases',pur,org,b,actor);
 perform public.reverse_record_atomic('estimates',est,org,b,actor);
 perform public.reverse_record_atomic('customers',c,org,b,actor);
 if exists(select 1 from public.inventory where product_id in(p,q) and quantity<>0) then raise exception 'Surviving stock did not reconcile to zero';end if;
 if exists(select 1 from public.customers where id=c) or exists(select 1 from public.purchases where id=pur) then raise exception 'Records not deleted';end if;
 if (select count(*) from public.audit_logs where organization_id=org)<>7 then raise exception 'Audit count mismatch';end if;
 if exists(select l.account_id from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.organization_id=org group by l.account_id having sum(l.debit-l.credit)<>0) then raise exception 'GL did not reconcile';end if;
 if exists(select 1 from public.customer_ledger_entries where organization_id=org) or exists(select 1 from public.vendor_payable_ledger_entries where organization_id=org) then raise exception 'Party ledger effects survived';end if;
 if (select count(*) from public.journal_entries where organization_id=org and posting_kind='PRIMARY')<>5 or (select count(*) from public.journal_entries where organization_id=org and posting_kind='REVERSAL')<>5 then raise exception 'Journal history was lost';end if;
 begin delete from public.audit_logs where organization_id=org;raise exception 'Audit deletion accepted';exception when check_violation then null;end;
 begin update public.audit_logs set action='VOID' where organization_id=org;raise exception 'Audit edit accepted';exception when check_violation then null;end;
 begin perform public.record_purchase(org,b,actor,'reversal-regression','purchase.create',v,w,jsonb_build_array(jsonb_build_object('product_id',p,'quantity',5,'unit_cost',1200),jsonb_build_object('product_id',q,'quantity',5,'unit_cost',300)),'purchase',repeat('1',64));raise exception 'Deleted purchase replay accepted';exception when check_violation then null;end;
 if public.reverse_record_atomic('invoices',inv,org,b,actor) is not null then raise exception 'Deleted invoice reappeared';end if;
 begin perform public.reverse_record_atomic('vendors',v,gen_random_uuid(),b,actor);raise exception 'Foreign tenant accepted';exception when insufficient_privilege then null;end;
end $$;
rollback;
